import React, { useState } from 'react'

const Tabs = () => {
  const [activeTab, setActiveTab] = useState('page-one')
  return (
    <div>
        <div>
            <button onClick={() => setActiveTab('page-one')}>Page One</button>
            <button onClick={() => setActiveTab('page-two')}>Page Two</button>
        </div>
        {activeTab === 'page-one' && <PageOne />}
        {activeTab === 'page-two' && <PageTwo />}
    </div>
  )
}

export default Tabs
